<?php
require_once __DIR__.'/../config/bootstrap.php';$pageTitle='Relatórios';$date=$_GET['date']??date('Y-m-d');$s=$pdo->prepare("SELECT f.*,c.name carrier,o.city origin_city,d.city destination_city,GROUP_CONCAT(CONCAT(p.name,' (',fp.quantity,')') SEPARATOR ', ') products FROM freights f JOIN carriers c ON c.id=f.carrier_id JOIN addresses o ON o.id=f.origin_id JOIN addresses d ON d.id=f.destination_id LEFT JOIN freight_products fp ON fp.freight_id=f.id LEFT JOIN products p ON p.id=fp.product_id WHERE f.freight_date=? GROUP BY f.id ORDER BY f.id");$s->execute([$date]);$rows=$s->fetchAll();$download=isset($_GET['download']);
if($download){if(file_exists(__DIR__.'/../vendor/autoload.php')){require __DIR__.'/../vendor/autoload.php';$html='<html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans;font-size:11px;color:#24324a}h1{color:#3268d5}table{width:100%;border-collapse:collapse}th,td{border:1px solid #ddd;padding:8px;text-align:left}th{background:#edf3ff}</style></head><body><h1>LogiTrack — Relatório de fretes</h1><p>Data: '.date('d/m/Y',strtotime($date)).'</p><table><tr><th>Código</th><th>Transportador</th><th>Trajeto</th><th>Produtos</th><th>Status</th></tr>';foreach($rows as $r){$html.='<tr><td>#'.$r['id'].'</td><td>'.e($r['carrier']).'</td><td>'.e($r['origin_city'].' → '.$r['destination_city']).'</td><td>'.e($r['products']).'</td><td>'.e($r['status']).'</td></tr>';}$html.='</table></body></html>';$dompdf=new Dompdf\Dompdf();$dompdf->loadHtml($html,'UTF-8');$dompdf->setPaper('A4','landscape');$dompdf->render();$dompdf->stream('relatorio-fretes-'.$date.'.pdf');exit;}else{header('Content-Type: text/html; charset=utf-8');echo '<script>window.onload=()=>window.print()</script>';}}
require __DIR__.'/../includes/header.php';?>
<div class="page-heading"><div><span class="eyebrow">ANÁLISES</span><h1>Relatório de fretes</h1><p>Consulte as operações realizadas em uma data específica.</p></div></div>
<section class="panel"><div class="panel-heading"><div><h2>Filtrar por data</h2><p>Escolha o dia desejado para gerar o relatório.</p></div></div><div class="p-4"><form class="filter-bar" method="get"><div><label class="form-label">Data do frete</label><input class="form-control" type="date" name="date" value="<?=e($date)?>" required></div><button class="btn btn-primary">Consultar</button><a class="btn btn-light" href="<?=e(url('reports/freights.php?date='.urlencode($date).'&download=1'))?>">Baixar PDF / Imprimir</a></form></div></section>
<section class="panel"><div class="panel-heading"><div><h2>Resultado</h2><p><?=count($rows)?> frete(s) encontrado(s) em <?=e(date('d/m/Y',strtotime($date)))?>.</p></div></div><div class="table-wrap"><table><thead><tr><th>Código</th><th>Transportador</th><th>Trajeto</th><th>Produtos</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td>#<?=$r['id']?></td><td><?=e($r['carrier'])?></td><td><?=e($r['origin_city'].' → '.$r['destination_city'])?></td><td><?=e($r['products'])?></td><td><?=e($r['status'])?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5">Nenhum frete encontrado para esta data.</td></tr><?php endif;?></tbody></table></div></section>
<?php require __DIR__.'/../includes/footer.php';?>
